"""Item 0(a), 0(b): the group generated by q1, q2, its classes, its characters
(DERIVED here from the two generators), and the restriction of V_{l/2}, l <= 20.
"""
import json, os, sys
from fractions import Fraction as Fr
HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)
from lib_exact import Q5, PHI, qmul, qconj, qnorm2, qkey, q5
from lib_check import check, summary

half = Fr(1, 2)
q1 = (Q5(half), Q5(half), Q5(half), Q5(half))
phinv = PHI - 1  # 1/phi = phi - 1
check("phi * phinv == 1", PHI * phinv == Q5(1))
q2 = (PHI * half, phinv * half, Q5(half), Q5(0))
from lib_check import DEFECT
if DEFECT == "wrong_generator":  # planted: a unit quaternion generating a different group
    q2 = (Q5(half), Q5(half), Q5(half), Q5(-half))
print("0(a) |q1|^2 =", qnorm2(q1), "  |q2|^2 =", qnorm2(q2))
check("|q1| = 1 exactly", qnorm2(q1) == Q5(1))
check("|q2| = 1 exactly", qnorm2(q2) == Q5(1))

# closure
one = (Q5(1), Q5(0), Q5(0), Q5(0))
elems = {qkey(one): one}
frontier = [one]
while frontier:
    new = []
    for g in frontier:
        for s in (q1, q2):
            h = qmul(g, s)
            k = qkey(h)
            if k not in elems:
                elems[k] = h
                new.append(h)
    frontier = new
G = list(elems.values())
order = len(G)
print("0(a) order of Gamma_0 =", order)
check("group closed under products (random pairs)", all(qkey(qmul(G[a], G[(7 * a + 3) % order])) in elems for a in range(order)))
check("all elements unit", all(qnorm2(g) == Q5(1) for g in G))

# element orders
def elt_order(g):
    k, x = 1, g
    while qkey(x) != qkey(one):
        x = qmul(x, g)
        k += 1
    return k

# conjugacy classes
seen = set()
classes = []
for g in G:
    if qkey(g) in seen:
        continue
    cl = {}
    for x in G:
        c = qmul(qmul(x, g), qconj(x))
        cl[qkey(c)] = c
    for k in cl:
        seen.add(k)
    classes.append(list(cl.values()))
# order classes by (element order, real part)
classes.sort(key=lambda c: (elt_order(c[0]), float(c[0][0])))
reps = [c[0] for c in classes]
sizes = [len(c) for c in classes]
orders = [elt_order(c[0]) for c in classes]
re_parts = [c[0][0] for c in classes]
check("every class has a constant real part", all(all(x[0] == c[0][0] for x in c) for c in classes))
check("class sizes sum to order", sum(sizes) == order)
print("0(a) number of classes =", len(classes))
for k, c in enumerate(classes):
    print(f"   class {k}: size {sizes[k]:3d}, element order {orders[k]:2d}, real part w = {re_parts[k]}  (~{float(re_parts[k]):+.6f})")

# characters of V_j at a class: U_{2j}(w), Chebyshev of the 2nd kind (trace of D^j at an element
# with real part w = cos(theta), eigenvalues e^{+-i theta}).  Derived, exact in Q(sqrt5).
def chi_V(twoj, w):
    u0, u1 = Q5(1), w * 2
    if twoj == 0:
        return u0
    for _ in range(twoj - 1):
        u0, u1 = u1, w * 2 * u1 - u0
    return u1

def inner(c1, c2):  # characters here are real (checked below)
    s = Q5(0)
    for k in range(len(classes)):
        s = s + c1[k] * c2[k] * sizes[k]
    return s / order

def gal(c):
    return [x.conj() for x in c]

# inverse-closed classes => real characters
inv_ok = all(qkey(qconj(c[0])) in {qkey(x) for x in c} for c in classes)
check("every class contains the inverses of its elements (characters real)", inv_ok)

Vchars = {tj: [chi_V(tj, w) for w in re_parts] for tj in range(0, 41)}
irr = []      # list of (name, character)
log = []

def is_new(ch):
    return all(not all(a == b for a, b in zip(ch, c2)) for _, c2 in irr)

def add(name, ch):
    nrm = inner(ch, ch)
    deg = ch[0]
    ok = nrm == Q5(1) and deg.b == 0 and deg.a > 0 and deg.a.denominator == 1
    check(f"candidate {name}: norm 1 and positive integer degree", ok)
    irr.append((name, ch))

for tj in range(0, 41):
    ch = Vchars[tj]
    res = list(ch)
    for name, c in irr:
        m = inner(ch, c)
        res = [r - c[k] * m for k, r in enumerate(res)]
    if all(r.iszero() for r in res):
        continue
    # try Galois conjugates of known irreducibles
    for name, c in list(irr):
        gc = gal(c)
        if is_new(gc):
            m = inner(res, gc)
            if not m.iszero():
                add(name + "^sigma", gc)
                res = [r - gc[k] * m for k, r in enumerate(res)]
    if all(r.iszero() for r in res):
        continue
    if inner(res, res) == Q5(1):
        add(f"V_{tj}/2 - known", res) if tj > 0 else add("V_0", res)
    if sum(int(c[0].a) ** 2 for _, c in irr) == order:
        break

dims = [int(c[0].a) for _, c in irr]
print("0(a) irreducible characters found:", len(irr), "dims", dims, " sum of squares", sum(d * d for d in dims))
check("sum of squared dimensions = |Gamma_0|", sum(d * d for d in dims) == order)
check("number of irreducibles = number of classes", len(irr) == len(classes))
orth = all(inner(irr[a][1], irr[b][1]) == Q5(1 if a == b else 0) for a in range(len(irr)) for b in range(len(irr)))
check("characters orthonormal", orth)
# column orthogonality as an independent completeness test
colok = True
for k in range(len(classes)):
    for l in range(len(classes)):
        s = Q5(0)
        for _, c in irr:
            s = s + c[k] * c[l]
        want = Q5(Fr(order, sizes[k])) if k == l else Q5(0)
        colok = colok and s == want
check("column orthogonality", colok)

# multiplicities of each irreducible in V_{l/2}, l <= 20
mult = {}
for idx, (name, c) in enumerate(irr):
    mult[idx] = {l: int(inner(Vchars[l], c).a) for l in range(0, 21)}
    for l in range(21):
        assert inner(Vchars[l], c).b == 0
# give each irreducible a name from its dimension and its lowest level (labels only)
info = []
for idx, (name, c) in enumerate(irr):
    levels = {l: m for l, m in mult[idx].items() if m > 0}
    low = min(levels) if levels else None
    faithful = not (c[[k for k in range(len(classes)) if orders[k] == 2][0]] == c[0])
    info.append(dict(index=idx, derived_as=name, dim=dims[idx], lowest_level=low, levels=levels,
                     spinorial=faithful, character=[str(x) for x in c],
                     character_sympy=[str(x.sympy()) for x in c]))
info.sort(key=lambda d: (d["lowest_level"], d["dim"]))
print("\n0(a) character table (rows: irreducibles labelled dim@lowest level; columns: classes 0..8)")
for d in info:
    print(f"  {d['dim']}@{d['lowest_level']:2d}  ({d['derived_as']}):  " + ", ".join(d["character_sympy"]))
print("\n0(b) levels l <= 20 at which each irreducible occurs in V_{l/2}, with multiplicities")
for d in info:
    print(f"  {d['dim']}@{d['lowest_level']:2d}: " + ", ".join(f"l={l}:x{m}" for l, m in sorted(d["levels"].items())))

slots = {"R2": (2, 7), "R4": (3, 6), "R5": (4, 6)}
slot_index = {}
for sname, (dim, low) in slots.items():
    hits = [d for d in info if d["dim"] == dim and d["lowest_level"] == low]
    if not check(f"slot {sname} (dim {dim}, lowest level {low}) picks exactly one irreducible", len(hits) == 1):
        continue
    slot_index[sname] = hits[0]["index"]
    d = hits[0]
    check(f"slot {sname}: multiplicity one at its lowest level", d["levels"][low] == 1)
    print(f"  {sname} = {d['dim']}@{d['lowest_level']} ({d['derived_as']}); multiplicity at lowest level = {d['levels'][low]}")

os.makedirs(os.path.join(HERE, "out"), exist_ok=True)
if not DEFECT: json.dump(dict(order=order, class_sizes=sizes, class_orders=orders,
               class_real_parts=[str(w.sympy()) for w in re_parts],
               class_reps=[[str(c.sympy()) for c in r] for r in reps],
               irreducibles=info, slot_index=slot_index),
          open(os.path.join(HERE, "out", "group.json"), "w"), indent=1)
summary()
